// --- 追加到 smartyoutubetv/build.gradle 文件的底部（Groovy DSL） ---
def pwaAssetsDir = rootProject.file('pwaapp/src/main/assets')
def destAssetsDir = file('src/main/assets')

tasks.register('copyPwaAssets', Copy) {
    from pwaAssetsDir
    into destAssetsDir
    // 可按需 exclude('**/node_modules/**')
}

preBuild.dependsOn tasks.named('copyPwaAssets')
// --- 结束片段 ---
